#!/usr/bin/env node
/*
 * Bundles the REAL game sim + the run verifier into ONE self-contained ES module
 * that runs in Deno (the Supabase Edge Function) AND Node (for testing). The
 * Edge Function can't read our repo's src/game/ at deploy time, so we INLINE the
 * game source as real module source (Supabase's edge runtime blocks eval, so we
 * can't load it from a string). The game code is strict-mode safe (checked).
 *
 * Output: supabase/functions/submit-run/_sim.mjs  (generated — do not edit)
 * Regenerate whenever the sim changes:  node scripts/build-verifier.js
 * The verify logic here mirrors scripts/verify-run.js (which is the tested spec).
 */
'use strict';
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const campaigns = fs.readFileSync(path.join(root, 'src', 'campaigns.js'), 'utf8');
// The game is authored as ordered files in src/game/ and loaded by the page as
// ordered <script src> tags; this is the same source concatenated back into one
// string, byte-identical to the single inline <script> it replaced.
const game = require('./lib/game-source.js').gameSource(root);
const SIM_ID = require('./lib/sim-id.js').simId(root);

// the minimal surface the verifier drives, exposed on globalThis by the sim
const expose = `
;globalThis.__vg = {
  S, setState: v => { state = v; }, setIntro: v => { introT = v; introCd = 0; },
  startLevel, startWeekly, startEndless, startReplay, stopReplay, simStep, resetCanonical, setViewport, mutators,
  getState: () => state,
  CAMPAIGNS, installCampaign, campId: () => (CAMP ? CAMP.id : null),
  levelsN: () => (typeof LEVELS !== 'undefined' ? LEVELS.length : -1),
  campN: () => (typeof CAMPAIGNS !== 'undefined' ? CAMPAIGNS.length : -1),
  lvName: () => { try { return (LV && LV.name) || (LEVELS[levelIdx] && LEVELS[levelIdx].name) || null; } catch (e) { return 'ERR:' + e.message; } },
  stats: () => ({ score, integrity, misses, zaps, perfects, maxCombo, comboSec: maxComboSec })
};`;
// campaigns.js loads before the game <script> in the page — mirror that order.
const gameCode = (campaigns + '\n' + game + expose).replace("'use strict';", '');

// --- header: DOM/Web-API stubs, isolated so their locals don't collide with the sim ---
const header = `// AUTO-GENERATED by scripts/build-verifier.js — DO NOT EDIT.
// Headless sim + run verifier, self-contained for Deno (Supabase Edge Function) and Node.
(function () {
  const g = globalThis;
  function set(k, v) { try { g[k] = v; } catch (_) { try { Object.defineProperty(g, k, { value: v, configurable: true, writable: true }); } catch (__) {} } }
  const grad = { addColorStop() {} };
  let canvasStub;
  const ctxStub = new Proxy({}, { get: (t, k) => { if (k === 'canvas') return canvasStub; return (...a) => (String(k).startsWith('create') ? grad : (k === 'measureText' ? { width: 10 } : undefined)); }, set: () => true });
  canvasStub = { width: 0, height: 0, style: {}, getContext: () => ctxStub, addEventListener() {}, setPointerCapture() {} };
  set('document', { getElementById: () => canvasStub, createElement: () => ({ width: 0, height: 0, style: {}, getContext: () => ctxStub }), documentElement: {}, addEventListener() {}, hidden: false });
  function makeBuf() { const d = new Float32Array(10000); for (let i = 500; i < 9000; i++) d[i] = 0.5; return { sampleRate: 1000, length: 10000, duration: 10, getChannelData: () => d }; }
  class FakeGain { constructor() { this.gain = { value: 1, setValueAtTime() {}, exponentialRampToValueAtTime() {} }; } connect() {} disconnect() {} }
  class FakeSrc { constructor() { this.buffer = null; this.loop = false; this.loopStart = 0; this.loopEnd = 0; this.playbackRate = { value: 1 }; } connect() {} disconnect() {} start() { this.started = true; } stop() {} }
  class FakeAC { constructor() { this.state = 'running'; this.destination = {}; this.currentTime = 0; } createGain() { return new FakeGain(); } createBufferSource() { return new FakeSrc(); } createBiquadFilter() { return { type: '', frequency: { value: 0 }, Q: { value: 1 }, connect() {}, disconnect() {} }; } createOscillator() { return { type: '', frequency: { setValueAtTime() {}, exponentialRampToValueAtTime() {} }, connect() {}, start() {}, stop() {} }; } decodeAudioData() { return Promise.resolve(makeBuf()); } resume() { return Promise.resolve(); } suspend() { return Promise.resolve(); } }
  set('AudioContext', FakeAC);
  set('fetch', () => Promise.resolve({ arrayBuffer: () => Promise.resolve(new ArrayBuffer(8)) }));
  set('window', { innerWidth: 800, innerHeight: 450, devicePixelRatio: 1, addEventListener() {}, AudioContext: FakeAC, MUSIC_DATA: { menu: 'menu.mp3', levels: ['l1.mp3', 'l2.mp3', 'l3.mp3'] } });
  set('getComputedStyle', () => ({ getPropertyValue: () => '0px' }));
  // Deno/edge ship a REAL disk-backed localStorage; wipe it and force an inert
  // stub so no persisted save state (mutators/progress) leaks into the sim.
  try { g.localStorage && g.localStorage.clear && g.localStorage.clear(); } catch (_) {}
  set('localStorage', { getItem: () => null, setItem() {}, removeItem() {}, clear() {} });
  set('requestAnimationFrame', () => {});
  set('screen', {});
})();

// --- the real game sim, INLINED (wrapped so a load error is catchable) ---
(function () { try {
`;

// --- footer: the verifier, driving the exposed __vg ---
const footer = `
} catch (e) { globalThis.__loadErr = String((e && e.stack) || e); } })();

const __VG = globalThis.__vg;
function __warmUp(level) {
  __VG.startLevel(level | 0); __VG.setIntro(999); __VG.setState(__VG.S.PLAY);
  for (let i = 0; i < 4000 && __VG.getState() !== __VG.S.END; i++) __VG.simStep();
}
// verifyRun(run) → { ok, recomputed, expected, integrity, steps, reason }
export function verifyRun(run) {
  if (!__VG) return { ok: false, reason: 'sim not loaded', loadError: globalThis.__loadErr };
  if (!run || !Array.isArray(run.trace)) return { ok: false, reason: 'no trace' };
  if (run.mode === 'endless') return { ok: false, reason: 'endless is unseeded — unverifiable' };
  __VG.resetCanonical(); // save-state-independent baseline (mutators off, briefings seen)
  __VG.setViewport(run.w | 0, run.h | 0); // reproduce the run's geometry (headless W/H default to 0 → geo() NaN)
  if (Array.isArray(run.mutators)) for (const k of run.mutators) if (k in __VG.mutators) __VG.mutators[k] = true; // re-apply the run's OWN mutators
  // INSTALL THE RUN'S CAMPAIGN FIRST — levelIdx is an index INTO a campaign, so
  // without this every board outside campaign 1 was replayed against campaign 1's
  // level of the same number and silently rejected. A cold Edge Function starts on
  // the default campaign, so this MUST be set from the run, never inherited.
  if (run.mode !== 'weekly') {
    const camp = run.campId ? (__VG.CAMPAIGNS || []).find(c => c.id === run.campId) : null;
    if (run.campId && !camp) return { ok: false, reason: 'unknown campaign ' + run.campId };
    __VG.installCampaign(camp || __VG.CAMPAIGNS[0]);
  }
  __warmUp(run.levelIdx | 0);
  if (run.mode === 'weekly') {
    // the week index IS the seed, and startWeekly takes it — so the bundle no longer
    // overrides Date.now to reach the right lane. Whether that week is still OPEN is a
    // separate question, answered by boardKeyFor in index.ts, which is the trust
    // boundary; this only has to reproduce the lane the run claims.
    __VG.startWeekly(run.seed | 0);
  } else {
    __VG.startLevel(run.levelIdx | 0);
  }
  __VG.setIntro(999); __VG.setState(__VG.S.PLAY);
  __VG.startReplay(run.trace);
  let steps = 0;
  const cap = run.trace.length + 8;
  while (__VG.simStep() && steps < cap) steps++;
  __VG.stopReplay();
  const s = __VG.stats();
  return { ok: s.score === run.score, recomputed: s.score, expected: run.score, integrity: s.integrity, steps,
    zaps: s.zaps, misses: s.misses, perfects: s.perfects, maxCombo: s.maxCombo, comboSec: s.comboSec };
}
// The fingerprint of the source this bundle was cut from. The whole point is to
// make "is the deployed verifier stale?" answerable in one request instead of
// inferred from rejected scores — see scripts/verifier-status.js.
export const SIM_ID = ${JSON.stringify(SIM_ID)};
// health check: confirm the sim loads + installs campaigns + runs in this runtime.
export function _diag() {
  if (!__VG) return { simId: SIM_ID, loadError: globalThis.__loadErr || 'V undefined (sim exposed no __vg)' };
  __VG.resetCanonical(); __VG.setViewport(800, 450);
  __VG.startLevel(4); __VG.setIntro(999); __VG.setState(__VG.S.PLAY);
  const info = { simId: SIM_ID, levels: __VG.levelsN(), campaigns: __VG.campN(), lvName: __VG.lvName() };
  for (let i = 0; i < 300; i++) __VG.simStep();
  info.noInput = __VG.stats();
  return info;
}
`;

const bundle = header + gameCode + footer;
console.log('  sim id: ' + SIM_ID);
const outDir = path.join(root, 'supabase', 'functions', 'submit-run');
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(path.join(outDir, '_sim.mjs'), bundle);
console.log('wrote supabase/functions/submit-run/_sim.mjs (' + (bundle.length / 1024 | 0) + ' KB, no-eval inline)');
